    requireThat(Number.isInteger(decimals.value) && decimals.value >= 0 && decimals.value <= 18, 'TOKEN_DECIMALS_UNSUPPORTED');
    requireThat(typeof symbol.value === 'string' && symbol.value.length <= 64 &&
