// MIT. Approved SF88 order preparation and original SF101 file retrieval.
import { createHash } from 'node:crypto';
import { request as httpsRequest } from 'node:https';
import { lstat } from 'node:fs/promises';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { config, execution, operation } from '../sf88-operator-buyer-cli/config.mjs';
import { createPublicHttpsFetch } from '../sf31-buyer-client/public-transport.mjs';
import { prepareBuyerResponseFile } from '../sf31-buyer-client/response-file.mjs';
import { need, privatePath, readJson, validateHandoff, sha } from './checkout-config.mjs';
import { writePrivateJson } from './checkout.mjs';
import { canonicalDeliveryPath, verifyExistingDeliveryFile, resumeEntitledFile, inspectFileTransfer, resetFileTransfer } from './resumable-transfer.mjs';
export { inspectFileTransfer, resetFileTransfer } from './resumable-transfer.mjs';

const USAGE = `node purchase.mjs prepare --handoff MERCHANT_HANDOFF.json --config EXISTING_SF88_OPERATOR.json --out NEW_ORDER_OPERATOR.json
node purchase.mjs inspect --handoff MERCHANT_HANDOFF.json
node purchase.mjs retrieve --handoff MERCHANT_HANDOFF.json --out PRIVATE_NEW_FILE [--claim-env SF101_CLAIM_TOKEN] [--timeout-ms 30000] [--resume true|false]
node purchase.mjs transfer --handoff MERCHANT_HANDOFF.json --out PRIVATE_NEW_FILE
node purchase.mjs reset-transfer --handoff MERCHANT_HANDOFF.json --out PRIVATE_NEW_FILE

Review/enqueue/execute with the ORIGINAL SF88 CLI and durable inbox. retrieve only
downloads an existing SF101 entitlement; it never invokes a buyer, signer or payment.
An existing matching output is recovered locally without a network request.
Linux resumes the same retained transfer by default. transfer reads its state;
reset-transfer discards that transfer's partial bytes for an explicit fresh GET.`;

export async function preparePurchase({handoff:raw, configuration, output}) {
  const handoff = validateHandoff(raw), original = structuredClone(configuration);
  const {op} = execution(original);
  const current = new URL(op.url), expected = new URL(handoff.purchaseUrl);
  need(current.origin === expected.origin && current.pathname === expected.pathname && op.method === 'GET' && op.bodyFile === undefined,
    'HANDOFF_MUST_MATCH_SELECTED_BUYER_OPERATION');
  need([...current.searchParams.keys()].every(key => key === 'sf98_order') &&
    (current.searchParams.get('sf98_order') === null || current.searchParams.get('sf98_order') === handoff.orderReference),
    'EXISTING_BUYER_QUERY_CONFLICT');
  need(op.orderReference === undefined || op.orderReference === handoff.orderReference, 'EXISTING_BUYER_ORDER_CONFLICT');
  need(['scheme','network','asset','payTo'].every(key => op.expect[key] === handoff.payment[key]) &&
    BigInt(op.expect.maxAtomic) >= BigInt(handoff.payment.amount) &&
    (op.expect.maxTimeoutSeconds === undefined || op.expect.maxTimeoutSeconds >= handoff.payment.maxTimeoutSeconds),
    'HANDOFF_EXCEEDS_EXISTING_BUYER_TERMS');
  original.operation = operation({...op, url:handoff.purchaseUrl, orderReference:handoff.orderReference});
  execution(original);
  await writePrivateJson(privatePath(output), original);
  return {status:'ORIGINAL_SF88_ORDER_PREPARED', output, intentId:op.intentId,
    approvedUrl:original.operation.url, orderReference:handoff.orderReference,
    expectedFile:handoff.file, paymentAuthorization:'ORIGINAL_SF88_REVIEW_AND_EXECUTE_REQUIRED'};
}

/** Retain original public DNS/TLS/redirect behavior. The token is scoped to one
 * exact merchant delivery path, injected only into the trusted transport call.
 * It is never a caller-supplied SF31 payment Authorization header.
 */
function claimTransport(handoff, token, timeoutMs = 30000, trustedProxy = null) {
  const delivery = new URL(handoff.deliveryUrl);
  const hostname = delivery.hostname.toLowerCase().replace(/\.$/, '');
  return createPublicHttpsFetch({timeoutMs, trustedProxy, requestImpl:(options, callback) => {
    need(options.hostname === hostname && options.path === delivery.pathname && options.method === 'GET',
      'CLAIM_TOKEN_DESTINATION_MISMATCH');
    return httpsRequest({...options, headers:{...options.headers, authorization:'Bearer ' + token}}, callback);
  }});
}

function verifiedResponse(response, expected) {
  need(response instanceof Response && response.status === 200 && response.body, 'ENTITLEMENT_NOT_AVAILABLE');
  const hash = createHash('sha256'); let size = 0;
  const verifier = new TransformStream({
    transform(chunk, controller) {
      need(chunk instanceof Uint8Array, 'DELIVERY_CHUNK_INVALID');
      size += chunk.byteLength;
      need(size <= expected.bytes, 'DELIVERY_EXCEEDS_APPROVED_FILE');
      hash.update(chunk); controller.enqueue(chunk);
    },
    flush() {
      // The ORIGINAL writer only publishes after EOF. A wrong/missing last byte
      // fails the stream before its create-only final-path publication.
      need(size === expected.bytes && hash.digest('hex') === expected.sha256, 'DELIVERY_FINGERPRINT_MISMATCH');
    },
  });
  return new Response(response.body.pipeThrough(verifier), {status:response.status, headers:response.headers});
}

async function deliveryReceipt(path, handoff, saved, source) {
  const payload = {schema:'stellar-forge.sf101.buyer-file.v1', orderReference:handoff.orderReference,
    purchaseUrl:handoff.purchaseUrl, deliveryUrl:handoff.deliveryUrl,
    handoffSha256:sha(JSON.stringify(handoff)), file:{path:saved.path, sha256:saved.sha256, bytes:saved.bytes},
    observedAt:new Date().toISOString(), source,
    payment:'SEPARATE_ORIGINAL_BUYER_AND_MERCHANT_RECORDS', automaticPaymentRetry:false};
  try { await writePrivateJson(path, payload); return {path, disposition:'WRITTEN'}; }
  catch (error) {
    if (error.code !== 'EEXIST') throw error;
    const old = await readJson(path);
    need(old?.schema === payload.schema && old.handoffSha256 === payload.handoffSha256 &&
      old.orderReference === payload.orderReference && old.file?.path === saved.path &&
      old.file.sha256 === saved.sha256 && old.file.bytes === saved.bytes, 'EXISTING_DELIVERY_RECEIPT_MISMATCH');
    return {path, disposition:'EXISTING_MATCH'};
  }
}

/** fetchImpl is a trusted embedding seam for actual local service acceptance.
 * trustedProxy selects the original explicit CONNECT transport while keeping
 * the claim token scoped to this exact delivery path inside claimTransport.
 * Choose one transport configuration. The normal CLI uses public DNS/TLS.
 */
export async function retrieveFile({handoff:raw, destination:requestedDestination, token, signal, fetchImpl,
  resume = process.platform === 'linux', timeoutMs = 30000, trustedProxy = null}) {
  const handoff = validateHandoff(raw);
  const destination = await canonicalDeliveryPath(requestedDestination);
  need(typeof resume === 'boolean', 'DELIVERY_RESUME_OPTION_INVALID');
  need(Number.isSafeInteger(timeoutMs) && timeoutMs > 0 && timeoutMs <= 300000, 'DELIVERY_TIMEOUT_INVALID');
  const receiptPath = destination + '.sf101.json';
  const local = await verifyExistingDeliveryFile(destination, handoff.file);
  if (local) {
    const saved = {path:local.path, bytes:local.bytes, sha256:local.sha256};
    if (resume) await inspectFileTransfer({handoff, destination});
    return {status:'EXISTING_LOCAL_BYTES_MATCH', orderReference:handoff.orderReference,
      file:saved, receipt:await deliveryReceipt(receiptPath, handoff, saved, 'EXISTING_LOCAL_FILE'), httpRequests:0};
  }
  try { await lstat(receiptPath); throw new Error('DELIVERY_RECEIPT_WITHOUT_FILE'); }
  catch (error) { if (error.code !== 'ENOENT') throw error; }
  need(fetchImpl === undefined || typeof fetchImpl === 'function', 'TRUSTED_DOWNLOAD_FETCH_REQUIRED');
  need(fetchImpl === undefined || trustedProxy === null, 'DELIVERY_TRANSPORT_CONFIGURATION_CONFLICT');
  async function fetchDelivery(headers, requestSignal) {
    need(typeof token === 'string' && Buffer.byteLength(token) >= 32 && Buffer.byteLength(token) <= 1024 &&
      !/[\x00-\x20\x7f]/.test(token), 'PRIVATE_CLAIM_TOKEN_REQUIRED');
    const transport = fetchImpl ?? claimTransport(handoff, token, timeoutMs, trustedProxy);
    return transport(handoff.deliveryUrl, {method:'GET', redirect:'manual',
      ...(requestSignal ? {signal:requestSignal} : {}),
      headers:{...headers, ...(fetchImpl ? {authorization:'Bearer ' + token, 'accept-encoding':'identity'} : {})}});
  }
  if (resume) {
    const result = await resumeEntitledFile({handoff, destination, signal, timeoutMs, fetchDelivery});
    const receipt = await deliveryReceipt(receiptPath, handoff, result.saved, 'ORIGINAL_SF101_HTTP_DELIVERY');
    return {status:'APPROVED_FILE_SAVED', orderReference:handoff.orderReference,
      file:result.saved, receipt, httpRequests:result.httpRequests, transfer:result.transfer};
  }
  const writer = await prepareBuyerResponseFile({destination, maxBytes:handoff.file.bytes, timeoutMs});
  let response;
  try {
    response = await fetchDelivery({}, signal);
    const checked = verifiedResponse(response, handoff.file);
    const saved = await writer.save({response:checked}, {signal});
    const receipt = await deliveryReceipt(receiptPath, handoff, saved, 'ORIGINAL_SF101_HTTP_DELIVERY');
    return {status:'APPROVED_FILE_SAVED', orderReference:handoff.orderReference, file:saved, receipt, httpRequests:1};
  } finally {
    if (response?.body && !response.body.locked && !response.bodyUsed) try { await response.body.cancel(); } catch {}
    await writer.abort();
  }
}

export async function main(args = process.argv.slice(2)) {
  if (args.length === 1 && args[0] === '--help') { console.log(USAGE); return; }
  const action = args[0]; need(['prepare','inspect','retrieve','transfer','reset-transfer'].includes(action), 'PURCHASE_ACTION_REQUIRED');
  const allowed = {prepare:['--handoff','--config','--out'], inspect:['--handoff'],
    retrieve:['--handoff','--out','--claim-env','--timeout-ms','--resume'],
    transfer:['--handoff','--out'], 'reset-transfer':['--handoff','--out']}[action], values = new Map();
  for (let i=1; i<args.length; i+=2) {
    need(allowed.includes(args[i]) && !values.has(args[i]) && args[i+1] && !args[i+1].startsWith('--'), 'PURCHASE_OPTION_INVALID');
    values.set(args[i], args[i+1]);
  }
  need(values.has('--handoff'), 'PURCHASE_HANDOFF_REQUIRED');
  const handoff = validateHandoff(await readJson(resolve(values.get('--handoff'))));
  let result;
  if (action === 'inspect') result = {status:'MERCHANT_ORDER_REVIEW', ...handoff,
    approval:'ORIGINAL_SF88_REVIEW_AND_EXECUTE_REQUIRED', claimToken:'SEPARATE_PRIVATE_CHANNEL'};
  if (action === 'prepare') {
    need(values.has('--config') && values.has('--out'), 'BUYER_CONFIG_AND_OUTPUT_REQUIRED');
    result = await preparePurchase({handoff, configuration:await config(resolve(values.get('--config'))), output:resolve(values.get('--out'))});
  }
  if (action === 'retrieve') {
    need(values.has('--out'), 'PRIVATE_DELIVERY_OUTPUT_REQUIRED');
    const name = values.get('--claim-env') ?? 'SF101_CLAIM_TOKEN';
    need(/^[A-Z][A-Z0-9_]{1,64}$/.test(name), 'CLAIM_ENV_NAME_INVALID');
    need(!values.has('--resume') || ['true','false'].includes(values.get('--resume')), 'DELIVERY_RESUME_OPTION_INVALID');
    need(!values.has('--timeout-ms') || /^[1-9][0-9]{0,5}$/.test(values.get('--timeout-ms')), 'DELIVERY_TIMEOUT_INVALID');
    const controller = new AbortController();
    const stop = () => controller.abort(Object.assign(new Error('DELIVERY_ABORTED'), {code:'DELIVERY_ABORTED'}));
    process.once('SIGINT', stop); process.once('SIGTERM', stop);
    try {
      result = await retrieveFile({handoff, destination:resolve(values.get('--out')), token:process.env[name],
        signal:controller.signal, timeoutMs:Number(values.get('--timeout-ms') ?? 30000),
        resume:values.has('--resume') ? values.get('--resume') === 'true' : process.platform === 'linux'});
    } finally { process.removeListener('SIGINT', stop); process.removeListener('SIGTERM', stop); }
  }
  if (action === 'transfer' || action === 'reset-transfer') {
    need(values.has('--out'), 'PRIVATE_DELIVERY_OUTPUT_REQUIRED');
    const actionFunction = action === 'transfer' ? inspectFileTransfer : resetFileTransfer;
    result = await actionFunction({handoff, destination:resolve(values.get('--out'))});
  }
  console.log(JSON.stringify(result)); return result;
}
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url))
  main().catch(error => {
    console.error(JSON.stringify({error:/^[A-Z0-9_]+$/.test(error.code ?? '') ? error.code : 'PURCHASE_COMMAND_FAILED',
      ...(typeof error.partialPath === 'string' ? {partialPath:error.partialPath} : {}),
      ...(typeof error.transferState === 'string' ? {transferState:error.transferState, retainedBytes:error.retainedBytes,
        resumable:error.resumable, ...(error.checkpointError ? {checkpointError:error.checkpointError} : {})} : {}),
      automaticPaymentRetry:false}));
    process.exitCode=1;
  });

#!/usr/bin/env python3
"""SF101: authenticated SF98 merchant events -> durable paid file entitlements.

Python 3.11+ standard library. Bind loopback behind the merchant's HTTPS proxy.
The SF30 native seller and SF98 sender remain responsible for settlement/signing.
"""
from __future__ import annotations

import argparse
import hashlib
import hmac
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
import os
from pathlib import Path
import re
import secrets
import sqlite3
import stat
import sys
import tempfile
import time
from datetime import datetime, timezone
from urllib.parse import unquote

SCHEMA = "stellar-forge.sf98.webhook.v1"
MAX_BODY = 8192
MAX_FILE = 32 * 1024 * 1024
FILE_CHUNK = 64 * 1024
SPOOL_MEMORY = 1024 * 1024
TRANSFER_SCHEMA = "stellar-forge.sf101.byte-ranges.v1"
CLOCK_WINDOW = 300
ID_RE = re.compile(r"[a-f0-9]{64}\Z")
REF_RE = re.compile(r"[A-Za-z0-9._:-]{1,80}\Z")
ROUTE_RE = re.compile(r"[A-Za-z0-9_-]{1,80}\Z")
ATOMIC_RE = re.compile(r"[1-9][0-9]{0,49}\Z")
NETWORK_RE = re.compile(r"[A-Za-z0-9._:-]{3,100}\Z")
METHODS = {"GET", "HEAD", "POST", "PUT", "PATCH", "DELETE"}


def fail(reason: str) -> None:
    raise ValueError(reason)


def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def is_match(pattern: re.Pattern[str], value: object) -> bool:
    return isinstance(value, str) and pattern.fullmatch(value) is not None


def require_private_dir(raw: str, create: bool = False) -> Path:
    target = Path(raw)
    if not target.is_absolute() or str(target) == "/" or str(target) != os.path.normpath(raw):
        fail("Normalized absolute non-root --state required")
    if create:
        target.mkdir(mode=0o700, parents=False, exist_ok=True)
    info = target.lstat()
    if not stat.S_ISDIR(info.st_mode) or info.st_mode & 0o077:
        fail("State directory must be a real private 0700 directory")
    return target


def connect(state: Path) -> sqlite3.Connection:
    dbpath = state / "merchant.sqlite3"
    if dbpath.is_symlink() or not dbpath.is_file():
        fail("Run init first; existing real merchant.sqlite3 required")
    if dbpath.stat().st_mode & 0o077:
        fail("Database permissions must be 0600")
    db = sqlite3.connect(str(dbpath), timeout=5, isolation_level=None)
    db.row_factory = sqlite3.Row
    db.execute("PRAGMA busy_timeout=5000")
    db.execute("PRAGMA synchronous=FULL")
    try:
        migrate_recipient_binding(db)
    except Exception:
        db.close()
        raise
    return db


def migrate_recipient_binding(db: sqlite3.Connection) -> None:
    """Keep historical rows intact; their missing recipient stays explicitly unknown."""
    columns = {row[1] for row in db.execute("PRAGMA table_info(orders)")}
    if "recipient_digest" in columns:
        return
    if not columns:
        fail("Existing merchant database has no orders table; run init first")
    db.execute("BEGIN IMMEDIATE")
    try:
        # Recheck under the write lock when multiple workers start together.
        if "recipient_digest" not in {row[1] for row in db.execute("PRAGMA table_info(orders)")}:
            db.execute("ALTER TABLE orders ADD COLUMN recipient_digest TEXT")
        db.execute("COMMIT")
    except Exception:
        db.execute("ROLLBACK")
        raise


def init_state(state: Path) -> None:
    dbpath = state / "merchant.sqlite3"
    if dbpath.is_symlink():
        fail("Database must not be symlink")
    db = sqlite3.connect(dbpath)
    try:
        os.chmod(dbpath, 0o600)
        db.execute("PRAGMA journal_mode=WAL")
        db.execute("PRAGMA synchronous=FULL")
        db.executescript("""
        CREATE TABLE IF NOT EXISTS orders (
            order_ref TEXT PRIMARY KEY,
            route_id TEXT NOT NULL, method TEXT NOT NULL,
            network TEXT NOT NULL, amount_atomic TEXT NOT NULL,
            asset_digest TEXT NOT NULL, recipient_digest TEXT,
            file_path TEXT NOT NULL, file_sha256 TEXT NOT NULL,
            file_bytes INTEGER NOT NULL, token_sha256 TEXT NOT NULL,
            state TEXT NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','ENTITLED')),
            event_id TEXT UNIQUE,
            created_at TEXT NOT NULL, entitled_at TEXT
        );
        CREATE TABLE IF NOT EXISTS events (
            event_id TEXT PRIMARY KEY,
            payload_sha256 TEXT NOT NULL, order_ref TEXT NOT NULL UNIQUE,
            recorded_at TEXT NOT NULL,
            FOREIGN KEY(order_ref) REFERENCES orders(order_ref)
        );
        CREATE INDEX IF NOT EXISTS orders_state ON orders(state);
        """)
        db.commit()
        migrate_recipient_binding(db)
    finally:
        db.close()


class VerifiedPrivateFile:
    """One verified byte snapshot; the caller closes its private temporary spool."""

    def __init__(self, stream, digest: str, size: int):
        self.stream = stream
        self.sha256 = digest
        self.size = size

    @property
    def etag(self) -> str:
        return '"sha256-' + self.sha256 + '"'

    def close(self) -> None:
        self.stream.close()

    def __enter__(self):
        return self

    def __exit__(self, *_):
        self.close()


def file_identity(info) -> tuple:
    return (info.st_dev, info.st_ino, info.st_mode, info.st_size,
            info.st_mtime_ns, info.st_ctime_ns)


def snapshot_private_file(path: str, *, directory: Path | None = None) -> VerifiedPrivateFile:
    """Hash into a private spool before release, independent of later source edits.

    The original 32 MiB product cap remains. Only the first MiB is held in RAM;
    larger snapshots spill to an anonymous private temporary file. Reading the
    original descriptor again after hashing would allow a source edit to change
    already-authorized response bytes, so transfer reads only this snapshot.
    """
    target = Path(path)
    if not target.is_absolute() or os.path.normpath(path) != path:
        fail("Absolute normalized content file required")
    named = target.lstat()
    if not stat.S_ISREG(named.st_mode) or named.st_mode & 0o077 or not 0 < named.st_size <= MAX_FILE:
        fail("Content must be a private regular file, 1 byte to 32 MiB")
    flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_NONBLOCK", 0)
    fd = os.open(path, flags)
    snapshot = None
    try:
        info = os.fstat(fd)
        if file_identity(info) != file_identity(named):
            fail("Content changed while opening")
        snapshot = tempfile.SpooledTemporaryFile(max_size=SPOOL_MEMORY, mode="w+b", dir=directory)
        digest = hashlib.sha256()
        size = 0
        with os.fdopen(fd, "rb", closefd=False) as source:
            while chunk := source.read(FILE_CHUNK):
                size += len(chunk)
                if size > info.st_size or size > MAX_FILE:
                    fail("Content changed during read or exceeded 32 MiB")
                digest.update(chunk)
                snapshot.write(chunk)
        if size != info.st_size or file_identity(os.fstat(fd)) != file_identity(info):
            fail("Content changed during read")
        snapshot.seek(0)
        return VerifiedPrivateFile(snapshot, digest.hexdigest(), size)
    except BaseException:
        if snapshot is not None:
            snapshot.close()
        raise
    finally:
        os.close(fd)


def read_private_file(path: str) -> tuple[bytes, str]:
    """Compatibility interface for original callers that need the whole payload."""
    with snapshot_private_file(path) as content:
        return content.stream.read(), content.sha256


def get_private_env(name: str, *, minimum: int = 32) -> str:
    if not re.fullmatch(r"[A-Z][A-Z0-9_]{1,64}", name):
        fail("Invalid environment variable name")
    secret = os.environ.get(name, "")
    if not minimum <= len(secret.encode("utf-8")) <= 1024:
        fail("Required private secret missing or outside 32-1024 bytes")
    return secret


def enroll(args: argparse.Namespace, state: Path) -> dict:
    if not is_match(REF_RE, args.ref) or not is_match(ROUTE_RE, args.route):
        fail("Invalid order reference or route identifier")
    if args.method not in METHODS or not is_match(NETWORK_RE, args.network):
        fail("Invalid method or network")
    if not is_match(ATOMIC_RE, args.amount) or not is_match(ID_RE, args.asset_digest):
        fail("Positive atomic amount and 64-character SHA-256 asset digest required")
    if not is_match(ID_RE, args.recipient_digest):
        fail("64-character SHA-256 of the selected payTo recipient required")
    token = get_private_env(args.claim_env)
    with snapshot_private_file(args.file, directory=state) as content:
        digest, size = content.sha256, content.size
    created = datetime.now(timezone.utc).isoformat()
    with connect(state) as db:
        db.execute("""INSERT INTO orders (order_ref,route_id,method,network,amount_atomic,
                  asset_digest,recipient_digest,file_path,file_sha256,file_bytes,token_sha256,created_at)
                  VALUES (?,?,?,?,?,?,?,?,?,?,?,?)""", (
            args.ref, args.route, args.method, args.network, args.amount,
            args.asset_digest, args.recipient_digest, args.file, digest, size, sha(token.encode()), created,
        ))
    return {"orderRef": args.ref, "state": "PENDING", "sourceSha256": digest,
            "sourceBytes": size, "deliveryPath": "/deliver/" + args.ref}


def bind_recipient(args: argparse.Namespace, state: Path) -> dict:
    """Upgrade an unfulfilled historical order using its merchant-approved recipient."""
    if not is_match(REF_RE, args.ref) or not is_match(ID_RE, args.recipient_digest):
        fail("Existing order reference and selected recipient SHA-256 required")
    db = connect(state)
    try:
        db.execute("BEGIN IMMEDIATE")
        order = db.execute("SELECT * FROM orders WHERE order_ref=?", (args.ref,)).fetchone()
        if order is None:
            fail("Unknown order")
        if order["recipient_digest"] == args.recipient_digest:
            db.execute("COMMIT")
            return {"orderRef": args.ref, "status": "ALREADY_BOUND"}
        if order["recipient_digest"] is not None or order["state"] != "PENDING":
            fail("Only an unbound pending order can acquire a recipient")
        db.execute("UPDATE orders SET recipient_digest=? WHERE order_ref=?",
                   (args.recipient_digest, args.ref))
        db.execute("COMMIT")
        return {"orderRef": args.ref, "status": "RECIPIENT_BOUND"}
    except Exception:
        if db.in_transaction:
            db.execute("ROLLBACK")
        raise
    finally:
        db.close()


def validate_event(payload: object) -> dict:
    if not isinstance(payload, dict) or payload.get("schema") != SCHEMA:
        fail("Unknown event schema")
    required = {"schema", "eventId", "occurredAt", "routeId", "method", "network",
                "amountAtomic", "assetDigest", "orderReference", "settlement"}
    if set(payload) not in (required, required | {"recipientDigest"}):
        fail("Unexpected or missing event field")
    if "recipientDigest" in payload and not is_match(ID_RE, payload["recipientDigest"]):
        fail("Invalid selected recipient identity")
    if not is_match(ID_RE, payload["eventId"]) or not is_match(ROUTE_RE, payload["routeId"]):
        fail("Invalid event/route ID")
    if payload["method"] not in METHODS or not is_match(NETWORK_RE, payload["network"]):
        fail("Invalid method or network")
    if not is_match(ATOMIC_RE, payload["amountAtomic"]) or not is_match(ID_RE, payload["assetDigest"]):
        fail("Invalid payment identity")
    if not is_match(REF_RE, payload["orderReference"]):
        fail("Unbound merchant order reference")
    if payload["settlement"] != "ORIGINAL_NATIVE_SUCCESS":
        fail("Event is not original SF98 native-success notification")
    if not isinstance(payload["occurredAt"], str) or len(payload["occurredAt"]) > 40:
        fail("Invalid event time")
    try:
        dt = datetime.fromisoformat(payload["occurredAt"].replace("Z", "+00:00"))
        if dt.tzinfo is None:
            fail("Event time must have timezone")
    except (TypeError, ValueError):
        fail("Invalid event time")
    return payload


def accept_event(state: Path, payload: dict, raw_body: bytes) -> tuple[int, dict]:
    event_id, order_ref = payload["eventId"], payload["orderReference"]
    fingerprint = sha(raw_body)
    db = connect(state)
    try:
        db.execute("BEGIN IMMEDIATE")
        recorded = db.execute("SELECT * FROM events WHERE event_id=?", (event_id,)).fetchone()
        if recorded is not None:
            if recorded["payload_sha256"] != fingerprint or recorded["order_ref"] != order_ref:
                db.execute("ROLLBACK")
                return 409, {"code": "EVENT_REPLAY_CONFLICT"}
            db.execute("COMMIT")
            return 200, {"status": "ALREADY_ENTITLED", "eventId": event_id, "orderRef": order_ref}
        order = db.execute("SELECT * FROM orders WHERE order_ref=?", (order_ref,)).fetchone()
        if order is None:
            db.execute("ROLLBACK")
            return 404, {"code": "UNREGISTERED_ORDER"}
        if order["state"] != "PENDING":
            db.execute("ROLLBACK")
            return 409, {"code": "ORDER_ALREADY_USED"}
        pairs = (("route_id", "routeId"), ("method", "method"), ("network", "network"),
                 ("amount_atomic", "amountAtomic"), ("asset_digest", "assetDigest"))
        if any(order[left] != payload[right] for left, right in pairs):
            db.execute("ROLLBACK")
            return 409, {"code": "ORDER_PAYMENT_MISMATCH"}
        recipient = payload.get("recipientDigest")
        if order["recipient_digest"] != recipient:
            db.execute("ROLLBACK")
            return 409, {"code": "ORDER_RECIPIENT_NOT_BOUND" if order["recipient_digest"] is None
                         else "ORDER_RECIPIENT_MISMATCH"}
        recorded_at = datetime.now(timezone.utc).isoformat()
        db.execute("INSERT INTO events (event_id,payload_sha256,order_ref,recorded_at) VALUES (?,?,?,?)",
                   (event_id, fingerprint, order_ref, recorded_at))
        db.execute("UPDATE orders SET state='ENTITLED',event_id=?,entitled_at=? WHERE order_ref=? AND state='PENDING'",
                   (event_id, recorded_at, order_ref))
        db.execute("COMMIT")
        return 200, {"status": "ENTITLED", "eventId": event_id, "orderRef": order_ref}
    except Exception:
        if db.in_transaction:
            db.execute("ROLLBACK")
        raise
    finally:
        db.close()


def access_allowed(db: sqlite3.Connection, ref: str, now: float | None = None) -> bool:
    """Read only: merchant policy for an existing order, including pending checkout.

    Callers retain original enrollment/payment/entitlement checks. Absence of a
    configured policy preserves legacy access; it does not establish an order.
    Read the order and this policy inside the same explicit SQLite transaction.
    """
    if not is_match(REF_RE, ref):
        return False
    at = time.time() if now is None else now
    if isinstance(at, bool) or not isinstance(at, (int, float)) or not 0 <= at <= 253402300799:
        fail("Invalid access evaluation time")
    if not db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='sf101_access_policy'").fetchone():
        return True
    policy = db.execute("SELECT enabled,expires_at FROM sf101_access_policy WHERE order_ref=?", (ref,)).fetchone()
    return policy is None or (policy["enabled"] == 1 and
                              (policy["expires_at"] is None or at < policy["expires_at"]))


def get_entitled_snapshot(state: Path, ref: str, token: str) -> VerifiedPrivateFile | None:
    if not is_match(REF_RE, ref) or not 32 <= len(token.encode()) <= 1024:
        return None
    db = connect(state)
    try:
        # One snapshot binds original token/entitlement and access policy together.
        db.execute("BEGIN")
        order = db.execute("SELECT * FROM orders WHERE order_ref=?", (ref,)).fetchone()
        permitted = order is not None and access_allowed(db, ref)
        db.commit()
    finally:
        if db.in_transaction:
            db.rollback()
        db.close()
    if not permitted or order["state"] != "ENTITLED":
        return None
    actual = hashlib.sha256(token.encode()).digest()
    expected = bytes.fromhex(order["token_sha256"])
    if not hmac.compare_digest(actual, expected):
        return None
    content = snapshot_private_file(order["file_path"], directory=state)
    if content.size != order["file_bytes"] or content.sha256 != order["file_sha256"]:
        content.close()
        fail("Merchant source file no longer matches authorized order digest")
    return content


def get_entitled_file(state: Path, ref: str, token: str) -> bytes | None:
    """Preserve original embedding callers while HTTP uses a bounded-memory spool."""
    content = get_entitled_snapshot(state, ref, token)
    if content is None:
        return None
    with content:
        return content.stream.read()


class UnsatisfiableRange(ValueError):
    pass


def select_byte_range(value: str | None, size: int) -> tuple[int, int] | None:
    """Return one inclusive byte range; ignore unknown units and multipart sets."""
    if value is None:
        return None
    if len(value) > 512:
        fail("INVALID_BYTE_RANGE")
    unit, separator, specification = value.partition("=")
    if not separator:
        fail("INVALID_BYTE_RANGE")
    if unit.casefold() != "bytes":
        return None
    # RFC 9110 permits ignoring Range. This endpoint supports one part only.
    if "," in specification:
        return None
    match = re.fullmatch(r"([0-9]*)-([0-9]*)", specification.strip())
    if match is None or not any(match.groups()):
        fail("INVALID_BYTE_RANGE")
    first, last = match.groups()
    if not first:
        suffix = int(last)
        if suffix == 0 or size == 0:
            raise UnsatisfiableRange()
        return max(0, size - suffix), size - 1
    start = int(first)
    end = int(last) if last else size - 1
    if last and end < start:
        fail("INVALID_BYTE_RANGE")
    if start >= size:
        raise UnsatisfiableRange()
    return start, min(end, size - 1)


def etag_matches(values: list[str], etag: str, *, weak: bool = False) -> bool:
    """Evaluate an HTTP entity-tag list, preserving commas inside quoted tags."""
    value = ",".join(values).strip()
    if value == "*":
        return True
    tag = r'(?:W/)?"[\x21\x23-\x7e\x80-\xff]*"'
    if re.fullmatch(rf"[ \t]*{tag}[ \t]*(?:,[ \t]*{tag}[ \t]*)*", value) is None:
        return False
    return any((item.removeprefix("W/") if weak else item) == etag
               for item in re.findall(tag, value))


def make_handler(state: Path, secret: str):
    class MerchantHandler(BaseHTTPRequestHandler):
        protocol_version = "HTTP/1.1"
        server_version = "SCF-SF101"
        sys_version = ""

        def log_message(self, format, *args):
            # Do not place order references, bearer tokens, payment details or paths in stdout.
            return

        def reply(self, status: int, body: dict | bytes, content_type="application/json", *, extra_headers=None) -> None:
            raw = body if isinstance(body, bytes) else json.dumps(body, separators=(",", ":")).encode()
            self.send_response(status)
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(raw)))
            self.send_header("Cache-Control", "no-store")
            self.send_header("X-Content-Type-Options", "nosniff")
            self.send_header("Connection", "close")
            for name, value in (extra_headers or {}).items():
                self.send_header(name, value)
            self.end_headers()
            self.close_connection = True
            if self.command != "HEAD":
                self.wfile.write(raw)

        def one_header(self, name: str) -> str | None:
            values = self.headers.get_all(name, [])
            return values[0] if len(values) == 1 else None

        def do_POST(self) -> None:
            if self.path != "/sf98/events":
                return self.reply(404, {"code": "NOT_FOUND"})
            self.connection.settimeout(5)
            length = self.one_header("Content-Length")
            if self.headers.get("Transfer-Encoding") or length is None or not re.fullmatch(r"[1-9][0-9]{0,3}", length):
                return self.reply(400, {"code": "INVALID_BODY_FRAMING"})
            count = int(length)
            if count > MAX_BODY or self.one_header("Content-Type") != "application/json":
                return self.reply(413, {"code": "INVALID_CONTENT"})
            ts = self.one_header("X-SF98-Timestamp")
            signed = self.one_header("X-SF98-Signature")
            identity = self.one_header("Idempotency-Key")
            if (ts is None or not re.fullmatch(r"[1-9][0-9]{9,10}", ts) or
                abs(time.time() - int(ts)) > CLOCK_WINDOW or signed is None or
                re.fullmatch(r"sha256=[a-f0-9]{64}", signed) is None or
                not is_match(ID_RE, identity)):
                return self.reply(401, {"code": "INVALID_SIGNATURE_OR_TIMESTAMP"})
            try:
                body = self.rfile.read(count)
            except (TimeoutError, OSError):
                return self.reply(408, {"code": "READ_TIMEOUT"})
            if len(body) != count:
                return self.reply(400, {"code": "TRUNCATED_BODY"})
            expected = hmac.new(secret.encode(), ts.encode() + b"." + body, hashlib.sha256).hexdigest()
            if not hmac.compare_digest(expected, signed[7:]):
                return self.reply(401, {"code": "INVALID_SIGNATURE_OR_TIMESTAMP"})
            try:
                event = validate_event(json.loads(body))
            except (ValueError, TypeError, UnicodeDecodeError, json.JSONDecodeError):
                return self.reply(422, {"code": "INVALID_EVENT"})
            if event["eventId"] != identity:
                return self.reply(409, {"code": "EVENT_IDEMPOTENCY_CONFLICT"})
            try:
                status, result = accept_event(state, event, body)
                return self.reply(status, result)
            except Exception:
                return self.reply(503, {"code": "LOCAL_MERCHANT_STORE_UNAVAILABLE"})

        def do_GET(self) -> None:
            if self.path == "/health":
                return self.reply(200, {"service": "sf101-merchant-receiver", "status": "READY",
                                        "accessControls": "stellar-forge.sf101.access-policy.v1",
                                        "fileTransfer": TRANSFER_SCHEMA})
            if not self.path.startswith("/deliver/") or self.path.count("/") != 2:
                return self.reply(404, {"code": "NOT_FOUND"})
            reference = unquote(self.path[len("/deliver/"):])
            auth = self.one_header("Authorization")
            if auth is None or not auth.startswith("Bearer "):
                return self.reply(404, {"code": "NOT_FOUND"})
            try:
                content = get_entitled_snapshot(state, reference, auth[7:])
                if content is None:
                    return self.reply(404, {"code": "NOT_FOUND"})
            except Exception:
                return self.reply(503, {"code": "MERCHANT_SOURCE_UNAVAILABLE"})
            # All metadata and conditionals follow the original authorization and
            # exact-source checks. A resumed request re-evaluates current policy.
            with content:
                try:
                    return self.transfer(content)
                except (ConnectionError, TimeoutError, OSError):
                    # A disconnected buyer retains its own verified checkpoint.
                    # Never write an error body into an already-started file.
                    self.close_connection = True

        def do_HEAD(self) -> None:
            return self.do_GET()

        def transfer(self, content: VerifiedPrivateFile) -> None:
            self.connection.settimeout(30)
            etag = content.etag
            metadata = {"ETag": etag, "Accept-Ranges": "bytes"}
            if_match = self.headers.get_all("If-Match", [])
            if if_match and not etag_matches(if_match, etag):
                return self.reply(412, {"code": "FILE_PRECONDITION_FAILED"}, extra_headers=metadata)
            if_none = self.headers.get_all("If-None-Match", [])
            if if_none and etag_matches(if_none, etag, weak=True):
                self.send_response(304)
                self.send_header("ETag", etag)
                self.send_header("Cache-Control", "private, no-store, no-transform")
                self.send_header("Connection", "close")
                self.end_headers()
                self.close_connection = True
                return

            selected = None
            if self.command == "GET":
                ranges = self.headers.get_all("Range", [])
                if len(ranges) > 1:
                    return self.reply(400, {"code": "INVALID_BYTE_RANGE"})
                requested = ranges[0] if ranges else None
                if_range = self.headers.get_all("If-Range", [])
                if requested is not None and if_range and (len(if_range) != 1 or if_range[0].strip() != etag):
                    # There is no Last-Modified validator for an enrolled digest.
                    # A weak/date/mismatched validator selects the complete file.
                    requested = None
                try:
                    selected = select_byte_range(requested, content.size)
                except UnsatisfiableRange:
                    return self.reply(416, {"code": "BYTE_RANGE_NOT_SATISFIABLE"},
                                      extra_headers={**metadata, "Content-Range": f"bytes */{content.size}"})
                except ValueError:
                    return self.reply(400, {"code": "INVALID_BYTE_RANGE"})

            start, end = selected if selected is not None else (0, content.size - 1)
            remaining = end - start + 1
            self.send_response(206 if selected is not None else 200)
            self.send_header("Content-Type", "application/octet-stream")
            self.send_header("Content-Disposition", "attachment")
            self.send_header("Content-Length", str(remaining))
            self.send_header("ETag", etag)
            self.send_header("Accept-Ranges", "bytes")
            if selected is not None:
                self.send_header("Content-Range", f"bytes {start}-{end}/{content.size}")
            self.send_header("Cache-Control", "private, no-store, no-transform")
            self.send_header("X-Content-Type-Options", "nosniff")
            self.send_header("Connection", "close")
            self.end_headers()
            self.close_connection = True
            if self.command == "HEAD":
                return
            content.stream.seek(start)
            while remaining:
                chunk = content.stream.read(min(FILE_CHUNK, remaining))
                if not chunk:
                    raise OSError("Verified snapshot ended during transfer")
                self.wfile.write(chunk)
                remaining -= len(chunk)

    return MerchantHandler


def main(argv=None):
    parser = argparse.ArgumentParser(description="SF101 actual merchant order -> native SF98 event -> paid file delivery")
    sub = parser.add_subparsers(dest="command", required=True)
    for name in ("init", "enroll", "bind-recipient", "serve", "status", "receipt"):
        p = sub.add_parser(name)
        p.add_argument("--state", required=True)
        if name == "enroll":
            for key in ("ref", "route", "method", "network", "amount", "asset-digest", "recipient-digest", "file"):
                p.add_argument("--" + key, required=True)
            p.add_argument("--claim-env", default="SF101_CLAIM_TOKEN")
        elif name == "bind-recipient":
            p.add_argument("--ref", required=True)
            p.add_argument("--recipient-digest", required=True)
        elif name == "serve":
            p.add_argument("--host", default="127.0.0.1", choices=["127.0.0.1", "::1"])
            p.add_argument("--port", type=int, default=8472)
            p.add_argument("--secret-env", default="SF98_WEBHOOK_SECRET")
        elif name == "receipt":
            p.add_argument("--ref", required=True)
            p.add_argument("--out", required=True)
    args = parser.parse_args(argv)
    os.umask(0o077)
    state = require_private_dir(args.state, create=args.command == "init")
    if args.command == "init":
        init_state(state)
        result = {"schema": "stellar-forge.sf101.store.v1", "status": "READY"}
    elif args.command == "enroll":
        result = enroll(args, state)
    elif args.command == "bind-recipient":
        result = bind_recipient(args, state)
    elif args.command == "serve":
        if not 1 <= args.port <= 65535:
            fail("Port must be 1-65535")
        secret = get_private_env(args.secret_env)
        db = connect(state)
        db.close()
        with ThreadingHTTPServer((args.host, args.port), make_handler(state, secret)) as server:
            print(json.dumps({"status": "LISTENING", "host": args.host, "port": args.port}), flush=True)
            server.serve_forever(poll_interval=0.25)
        return
    elif args.command == "status":
        with connect(state) as db:
            counts = {row["state"]: row["n"] for row in db.execute("SELECT state,COUNT(*) n FROM orders GROUP BY state")}
            events = db.execute("SELECT COUNT(*) FROM events").fetchone()[0]
            legacy_pending = db.execute("SELECT COUNT(*) FROM orders WHERE state='PENDING' AND recipient_digest IS NULL").fetchone()[0]
        result = {"schema": "stellar-forge.sf101.status.v1", "pending": counts.get("PENDING", 0),
                  "entitled": counts.get("ENTITLED", 0), "uniqueEvents": events,
                  "legacyPendingWithoutRecipient": legacy_pending}
    elif args.command == "receipt":
        if not is_match(REF_RE, args.ref):
            fail("Invalid reference")
        with connect(state) as db:
            row = db.execute("SELECT * FROM orders WHERE order_ref=?", (args.ref,)).fetchone()
        if not row or row["state"] != "ENTITLED":
            fail("Order not entitled")
        output = Path(args.out)
        if not output.is_absolute() or str(output) != os.path.normpath(args.out):
            fail("Absolute output path required")
        receipt = {"schema": "stellar-forge.sf101.merchant-entitlement.v1", "orderRef": args.ref,
                   "eventId": row["event_id"], "routeId": row["route_id"], "network": row["network"],
                   "amountAtomic": row["amount_atomic"], "assetDigest": row["asset_digest"],
                   "recipientDigest": row["recipient_digest"],
                   "recipientBinding": "SELECTED_RECIPIENT" if row["recipient_digest"] else "LEGACY_UNSPECIFIED",
                   "fileSha256": row["file_sha256"], "fileBytes": row["file_bytes"],
                   "entitledAt": row["entitled_at"], "authority": "SF98_SIGNED_NATIVE_SUCCESS_NOTICE"}
        with output.open("x", encoding="utf-8") as f:
            os.chmod(output, 0o600)
            f.write(json.dumps(receipt, indent=2) + "\n")
            f.flush()
            os.fsync(f.fileno())
        result = {"status": "WRITTEN", "path": str(output)}
    print(json.dumps(result))


if __name__ == "__main__":
    try:
        main()
    except (ValueError, FileNotFoundError, sqlite3.Error, OSError) as exc:
        print("SF101_ERROR " + str(exc), file=sys.stderr)
        sys.exit(2)

// MIT. Resume the original SF101 entitlement through the original SF31 writer.
import { createHash, randomUUID } from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { constants } from 'node:fs';
import { open, lstat, realpath, rename, unlink } from 'node:fs/promises';
import { basename, dirname, join } from 'node:path';
import { prepareBuyerResponseFile } from '../sf31-buyer-client/response-file.mjs';
import { need, privatePath, sha, validateHandoff } from './checkout-config.mjs';

const SCHEMA = 'stellar-forge.sf101.file-transfer.v1';
const CHUNK = 64 * 1024;
const NOFOLLOW = constants.O_NOFOLLOW ?? 0;
const states = new Set(['NEW', 'PREPARING', 'TRANSFERRING', 'INTERRUPTED', 'REJECTED', 'COMPLETE']);
const privateRegular = info => info.isFile() && (info.mode & 0o077) === 0 && info.nlink === 1;
const codeOf = error => /^[A-Z0-9_]+$/.test(error?.code ?? '') ? error.code : 'FILE_TRANSFER_INTERRUPTED';

export async function canonicalDeliveryPath(destination) {
  privatePath(destination);
  need(!['.', '..'].includes(basename(destination)), 'PRIVATE_DELIVERY_OUTPUT_REQUIRED');
  return join(await realpath(dirname(destination)), basename(destination));
}

async function privateJson(path, optional = false) {
  let handle;
  try { handle = await open(path, constants.O_RDONLY | NOFOLLOW); }
  catch (error) { if (optional && error.code === 'ENOENT') return null; throw error; }
  try {
    const info = await handle.stat();
    need(privateRegular(info) && info.size <= 32768, 'PRIVATE_TRANSFER_RECORD_REQUIRED');
    const bytes = await handle.readFile();
    need(bytes.length <= 32768, 'TRANSFER_RECORD_TOO_LARGE');
    return {value: JSON.parse(new TextDecoder('utf-8', {fatal: true}).decode(bytes)), info};
  } finally { await handle.close(); }
}

function partialPath(path, destination) {
  need(typeof path === 'string' && path !== destination && dirname(path) === dirname(destination) &&
    /^\.x402-response-[a-f0-9-]{36}\.partial$/.test(basename(path)), 'TRANSFER_PARTIAL_PATH_INVALID');
  return path;
}

async function inspectPartial(path, destination, maxBytes, expected = null, finalFile = false) {
  if (!finalFile) partialPath(path, destination);
  const regular = info => finalFile ? info.isFile() &&
    (process.platform === 'win32' || (info.mode & 0o077) === 0) : privateRegular(info);
  const handle = await open(path, constants.O_RDONLY | NOFOLLOW);
  try {
    const before = await handle.stat();
    need(regular(before) && before.size >= 0 && before.size <= maxBytes, 'TRANSFER_PARTIAL_FILE_INVALID');
    const hash = createHash('sha256'), buffer = Buffer.allocUnsafe(CHUNK);
    let position = 0;
    while (position < before.size) {
      const {bytesRead} = await handle.read(buffer, 0, Math.min(CHUNK, before.size - position), position);
      need(bytesRead > 0, 'TRANSFER_PARTIAL_CHANGED');
      hash.update(buffer.subarray(0, bytesRead)); position += bytesRead;
    }
    const after = await handle.stat(), named = await lstat(path);
    need(regular(after) && regular(named) && before.dev === named.dev &&
      before.ino === named.ino && before.size === after.size &&
      before.mtimeMs === after.mtimeMs && before.ctimeMs === after.ctimeMs, 'TRANSFER_PARTIAL_CHANGED');
    const result = {path, bytes:position, sha256:hash.digest('hex'), dev:String(before.dev), ino:String(before.ino)};
    if (expected) need(['path', 'bytes', 'sha256', 'dev', 'ino'].every(key => result[key] === expected[key]),
      'TRANSFER_PARTIAL_CHANGED');
    return result;
  } finally { await handle.close(); }
}

export async function verifyExistingDeliveryFile(destination, expected) {
  let found;
  try { found = await inspectPartial(destination, destination, expected.bytes, null, true); }
  catch (error) {
    if (error.code === 'ENOENT') return null;
    throw Object.assign(new Error('EXISTING_DELIVERY_FILE_MISMATCH'), {code:'EXISTING_DELIVERY_FILE_MISMATCH', cause:error});
  }
  need(found.bytes === expected.bytes && found.sha256 === expected.sha256, 'EXISTING_DELIVERY_FILE_MISMATCH');
  return found;
}

async function removePartial(partial, destination) {
  if (!partial) return;
  partialPath(partial.path, destination);
  let info;
  try { info = await lstat(partial.path); }
  catch (error) { if (error.code === 'ENOENT') return; throw error; }
  need(privateRegular(info) && String(info.dev) === partial.dev && String(info.ino) === partial.ino,
    'TRANSFER_PARTIAL_CHANGED');
  await unlink(partial.path);
}

async function openSession(raw, inputDestination) {
  const handoff = validateHandoff(raw), destination = await canonicalDeliveryPath(inputDestination);
  need(process.platform === 'linux', 'RESUMABLE_TRANSFER_LINUX_FLOCK_REQUIRED');
  const directory = dirname(destination), statePath = destination + '.sf101-transfer.json';
  const leasePath = join(directory, '.' + basename(destination) + '.sf101-transfer.lock');
  const reservationPath = join(directory, '.' + basename(destination) + '.x402-download.lock');
  const lease = await open(leasePath, constants.O_CREAT | constants.O_RDWR | NOFOLLOW, 0o600);
  let closed = false, state;
  async function assertLease() {
    need(!closed, 'FILE_TRANSFER_CLOSED');
    const [owned, named] = await Promise.all([lease.stat(), lstat(leasePath)]);
    need(privateRegular(owned) && privateRegular(named) && owned.dev === named.dev && owned.ino === named.ino,
      'FILE_TRANSFER_LEASE_CHANGED');
  }
  async function persist(changes) {
    await assertLease();
    const next = {...state, ...changes, revision:state.revision + 1, updatedAt:new Date().toISOString()};
    const temp = join(directory, '.sf101-transfer-' + randomUUID() + '.tmp');
    let file;
    try {
      file = await open(temp, constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | NOFOLLOW, 0o600);
      await file.writeFile(JSON.stringify(next) + '\n'); await file.sync(); await file.close(); file = null;
      await assertLease(); await rename(temp, statePath); state = next;
      const dir = await open(directory, constants.O_RDONLY | constants.O_DIRECTORY | NOFOLLOW);
      try { await dir.sync(); } finally { await dir.close(); }
    } finally { await file?.close().catch(() => {}); await unlink(temp).catch(() => {}); }
    return state;
  }
  function validatePartial(value) {
    if (value === null) return;
    need(value && typeof value === 'object', 'TRANSFER_RECORD_INVALID');
    partialPath(value.path, destination);
    need(Number.isSafeInteger(value.bytes) && value.bytes >= 0 && value.bytes <= handoff.file.bytes &&
      /^[a-f0-9]{64}$/.test(value.sha256 ?? '') && /^\d+$/.test(value.dev ?? '') &&
      /^\d+$/.test(value.ino ?? ''), 'TRANSFER_RECORD_INVALID');
  }
  try {
    await assertLease();
    const acquired = spawnSync('flock', ['--exclusive', '--nonblock', '--conflict-exit-code', '73', '3'],
      {stdio:['ignore', 'pipe', 'pipe', lease.fd], timeout:10000});
    need(!acquired.error && acquired.status === 0,
      acquired.status === 73 ? 'FILE_TRANSFER_ACTIVE' : 'RESUMABLE_TRANSFER_LINUX_FLOCK_REQUIRED');
    const record = await privateJson(statePath, true);
    state = record?.value ?? {schema:SCHEMA, handoffSha256:sha(JSON.stringify(handoff)), destination,
      expected:handoff.file, etag:'"sha256-' + handoff.file.sha256 + '"', status:'NEW', revision:0,
      attempts:0, partial:null, active:null, reservationTag:null};
    need(state?.schema === SCHEMA && state.handoffSha256 === sha(JSON.stringify(handoff)) &&
      state.destination === destination && state.expected?.bytes === handoff.file.bytes &&
      state.expected?.sha256 === handoff.file.sha256 && state.etag === '"sha256-' + handoff.file.sha256 + '"' &&
      states.has(state.status) && Number.isSafeInteger(state.revision) && state.revision >= 0 &&
      Number.isSafeInteger(state.attempts) && state.attempts >= 0, 'TRANSFER_HANDOFF_MISMATCH');
    validatePartial(state.partial);
    if (state.active) partialPath(state.active.path, destination);
    if (state.discarded) validatePartial(state.discarded);
    if (state.reservationTag !== null) need(/^sf101-[a-f0-9-]{36}$/.test(state.reservationTag ?? ''), 'TRANSFER_RECORD_INVALID');
    if (state.discarded) {
      await removePartial(state.discarded, destination);
      await persist({discarded:null});
    }
    const completed = await verifyExistingDeliveryFile(destination, handoff.file);
    if (!completed && state.status === 'COMPLETE') await persist({status:'NEW', completedFile:null,
      lastError:'PREVIOUS_DELIVERY_FILE_MISSING'});
    if (completed && state.status !== 'COMPLETE') {
      const original = await privateJson(reservationPath, true);
      if (original && state.reservationTag && original.value.reservationTag === state.reservationTag &&
          original.value.destination === destination && (!state.active || original.value.partialPath === state.active.path)) {
        const activePath = partialPath(original.value.partialPath, destination);
        let named;
        try { named = await lstat(activePath); } catch (error) { if (error.code !== 'ENOENT') throw error; }
        if (named && named.isFile() && (named.mode & 0o077) === 0 &&
            String(named.dev) === completed.dev && String(named.ino) === completed.ino) await unlink(activePath);
        const reservationInfo = await lstat(reservationPath);
        need(reservationInfo.dev === original.info.dev && reservationInfo.ino === original.info.ino,
          'TRANSFER_RESERVATION_CHANGED');
        await unlink(reservationPath);
      }
      await removePartial(state.partial, destination);
      await persist({status:'COMPLETE', partial:null, active:null, reservationTag:null, lastError:null,
        completedFile:{path:destination, bytes:completed.bytes, sha256:completed.sha256}, lastMode:'EXISTING_LOCAL_FILE'});
    }

    // A live owner holds the retained file-description flock even in another PID
    // namespace. Only an exact original SF31 reservation from this generation is
    // reclaimed; a legacy/unrelated writer's reservation is never removed.
    if (['PREPARING', 'TRANSFERRING'].includes(state.status)) {
      const reservation = await privateJson(reservationPath, true);
      let activePath = state.active?.path;
      if (reservation) {
        const original = reservation.value;
        need(original.destination === destination && original.reservationTag === state.reservationTag &&
          (!activePath || original.partialPath === activePath), 'TRANSFER_RESERVATION_UNRECOGNIZED');
        activePath = partialPath(original.partialPath, destination);
        const named = await lstat(reservationPath);
        need(named.dev === reservation.info.dev && named.ino === reservation.info.ino,
          'TRANSFER_RESERVATION_CHANGED');
        await unlink(reservationPath);
      }
      let active = null;
      if (activePath) {
        try { active = await inspectPartial(activePath, destination, handoff.file.bytes); }
        catch (error) { if (error.code !== 'ENOENT') throw error; }
      }
      let previous = state.partial;
      if (previous) previous = await inspectPartial(previous.path, destination, handoff.file.bytes, previous);
      const retained = active && (!previous || active.bytes >= previous.bytes) ? active : previous;
      const other = retained === active ? previous : active;
      const rejected = retained?.bytes === handoff.file.bytes && retained.sha256 !== handoff.file.sha256;
      await persist({status:rejected ? 'REJECTED' : 'INTERRUPTED', partial:retained,
        active:null, reservationTag:null, lastError:'PREVIOUS_PROCESS_INTERRUPTED'});
      if (other && other.path !== retained?.path) await removePartial(other, destination);
    }
  } catch (error) { closed = true; await lease.close(); throw error; }

  return {
    handoff, destination, statePath, get state() { return state; }, persist, assertLease,
    async close() { if (!closed) { closed = true; await lease.close(); } },
  };
}

function validateResponse(response, expected, etag, offset) {
  need(response instanceof Response && response.body && !response.bodyUsed && !response.body.locked,
    'ENTITLEMENT_NOT_AVAILABLE');
  if (response.status === 412) need(false, 'DELIVERY_SOURCE_CHANGED');
  need(response.status === 200 || (offset > 0 && response.status === 206), 'ENTITLEMENT_NOT_AVAILABLE');
  const encoding = response.headers.get('content-encoding');
  need(encoding === null || encoding.trim().toLowerCase() === 'identity', 'DELIVERY_ENCODING_CHANGED');
  const responseTag = response.headers.get('etag');
  if (responseTag !== null) need(responseTag === etag, 'DELIVERY_SOURCE_CHANGED');
  const resumed = response.status === 206 ? offset : 0;
  if (resumed) {
    need(responseTag === etag && response.headers.get('content-range') ===
      'bytes ' + resumed + '-' + (expected.bytes - 1) + '/' + expected.bytes, 'DELIVERY_RANGE_MISMATCH');
  } else need(response.headers.get('content-range') === null, 'DELIVERY_RANGE_MISMATCH');
  const length = response.headers.get('content-length');
  if (length !== null) need(/^\d+$/.test(length) && Number(length) === expected.bytes - resumed,
    'DELIVERY_LENGTH_MISMATCH');
  return resumed;
}

async function composedResponse(prefix, response, totalBytes) {
  let file = null, remote = null, offset = 0, closed = false;
  if (prefix?.bytes) file = await open(prefix.path, constants.O_RDONLY | NOFOLLOW);
  if (response?.body) remote = response.body.getReader();
  async function close() {
    if (closed) return;
    closed = true;
    await file?.close().catch(() => {}); file = null;
    if (remote) { try { remote.releaseLock(); } catch {} }
  }
  const body = new ReadableStream({
    async pull(controller) {
      try {
        if (file && offset < prefix.bytes) {
          const chunk = Buffer.allocUnsafe(Math.min(CHUNK, prefix.bytes - offset));
          const {bytesRead} = await file.read(chunk, 0, chunk.length, offset);
          need(bytesRead > 0, 'TRANSFER_PARTIAL_CHANGED');
          offset += bytesRead; controller.enqueue(chunk.subarray(0, bytesRead)); return;
        }
        if (file) { await file.close(); file = null; }
        if (remote) {
          const next = await remote.read();
          if (!next.done) { controller.enqueue(next.value); return; }
        }
        await close(); controller.close();
      } catch (error) { await close(); controller.error(error); }
    },
    async cancel(reason) {
      if (remote) { try { void remote.cancel(reason).catch(() => {}); } catch {} }
      await close();
    },
  });
  const headers = new Headers(response?.headers);
  headers.delete('content-range'); headers.set('content-length', String(totalBytes));
  return new Response(body, {status:200, headers});
}

/** Owns transfer recovery only. fetchDelivery must use the original exact-path
 * entitlement transport; no buyer, signer, ledger or payment operation is called. */
export async function resumeEntitledFile({handoff, destination, fetchDelivery, signal, timeoutMs = 30000}) {
  need(Number.isSafeInteger(timeoutMs) && timeoutMs > 0 && timeoutMs <= 300000, 'DELIVERY_TIMEOUT_INVALID');
  need(signal === undefined || signal instanceof AbortSignal, 'DELIVERY_SIGNAL_INVALID');
  const session = await openSession(handoff, destination);
  let writer, response, previous = session.state.partial, httpRequests = 0, timer = null;
  const controller = new AbortController();
  const abort = () => controller.abort(signal.reason);
  if (signal?.aborted) abort(); else signal?.addEventListener('abort', abort, {once:true});
  try {
    need(session.state.status !== 'REJECTED', 'TRANSFER_RESTART_REQUIRED');
    if (previous) previous = await inspectPartial(previous.path, session.destination, session.handoff.file.bytes, previous);
    const localComplete = previous?.bytes === session.handoff.file.bytes;
    if (localComplete) need(previous.sha256 === session.handoff.file.sha256, 'TRANSFER_RESTART_REQUIRED');
    if (controller.signal.aborted) throw controller.signal.reason;
    const reservationTag = 'sf101-' + randomUUID();
    await session.persist({status:'PREPARING', reservationTag, active:null, lastError:null});
    writer = await prepareBuyerResponseFile({destination:session.destination, maxBytes:session.handoff.file.bytes,
      expectedBytes:session.handoff.file.bytes, expectedSha256:session.handoff.file.sha256, timeoutMs, reservationTag});
    await session.persist({status:'TRANSFERRING', active:{path:writer.partialPath}, attempts:session.state.attempts + 1});
    let resumedBytes = localComplete ? previous.bytes : 0, mode = localComplete ? 'LOCAL_PARTIAL' : 'FULL';
    timer = setTimeout(() => controller.abort(Object.assign(new Error('DELIVERY_TIMEOUT'), {code:'DELIVERY_TIMEOUT'})), timeoutMs);
    if (!localComplete) {
      const headers = {};
      if (previous?.bytes) {
        headers.range = 'bytes=' + previous.bytes + '-';
        headers['if-range'] = session.state.etag;
        headers['if-match'] = session.state.etag;
      }
      httpRequests = 1;
      response = await fetchDelivery(headers, controller.signal);
      resumedBytes = validateResponse(response, session.handoff.file, session.state.etag, previous?.bytes ?? 0);
      mode = resumedBytes ? 'RESUMED' : previous?.bytes ? 'RESTARTED_FULL_RESPONSE' : 'FULL';
    }
    const composed = await composedResponse(resumedBytes ? previous : null, response, session.handoff.file.bytes);
    const saved = await writer.save({response:composed}, {signal:controller.signal});
    clearTimeout(timer);
    await session.persist({status:'COMPLETE', partial:null, active:null, reservationTag:null, lastError:null,
      completedFile:{path:saved.path, bytes:saved.bytes, sha256:saved.sha256}, lastMode:mode});
    const cleanupWarnings = [...saved.cleanupWarnings];
    try { await removePartial(previous, session.destination); }
    catch (error) { cleanupWarnings.push({path:previous?.path, code:codeOf(error)}); }
    return {saved:{...saved, cleanupWarnings}, httpRequests, transfer:{mode, resumedBytes,
      receivedBytes:saved.bytes - resumedBytes, statePath:session.statePath}};
  } catch (error) {
    if (!(error instanceof Error)) error = Object.assign(new Error('FILE_TRANSFER_INTERRUPTED'), {code:'FILE_TRANSFER_INTERRUPTED'});
    // Save the exact partial produced by SF31, then retire the older checkpoint.
    // If persistence fails, the active generation stays recoverable next launch.
    await writer?.abort().catch(() => {});
    let retained = previous;
    if (typeof error.partialPath === 'string') {
      const candidate = await inspectPartial(error.partialPath, session.destination, session.handoff.file.bytes);
      if (!retained || candidate.bytes >= retained.bytes) retained = candidate;
    }
    const rejected = retained?.bytes === session.handoff.file.bytes && retained.sha256 !== session.handoff.file.sha256;
    try {
      await session.persist({status:rejected ? 'REJECTED' : 'INTERRUPTED', partial:retained,
        active:null, reservationTag:null, lastError:codeOf(error)});
      if (previous && retained?.path !== previous.path) await removePartial(previous, session.destination);
      if (error.partialPath && retained?.path !== error.partialPath) {
        const unused = await inspectPartial(error.partialPath, session.destination, session.handoff.file.bytes);
        await removePartial(unused, session.destination);
      }
    } catch (checkpointError) {
      error.checkpointError = codeOf(checkpointError);
    }
    error.transferState = session.statePath;
    error.partialPath = retained?.path ?? error.partialPath ?? null;
    error.retainedBytes = retained?.bytes ?? 0;
    error.resumable = Boolean(retained && !rejected);
    throw error;
  } finally {
    clearTimeout(timer); signal?.removeEventListener('abort', abort);
    if (response?.body && !response.body.locked && !response.bodyUsed) {
      try { void response.body.cancel().catch(() => {}); } catch {}
    }
    await writer?.abort().catch(() => {});
    await session.close();
  }
}

export async function inspectFileTransfer({handoff, destination}) {
  const session = await openSession(handoff, destination);
  try {
    const partial = session.state.partial ? await inspectPartial(session.state.partial.path,
      session.destination, session.handoff.file.bytes, session.state.partial) : null;
    return {status:session.state.status, destination:session.destination, statePath:session.statePath,
      retainedBytes:partial?.bytes ?? 0, expectedBytes:session.handoff.file.bytes,
      attempts:session.state.attempts, resumable:partial !== null && session.state.status !== 'REJECTED',
      ...(partial ? {partialPath:partial.path} : {}),
      ...(session.state.lastError ? {lastError:session.state.lastError} : {})};
  } finally { await session.close(); }
}

export async function resetFileTransfer({handoff, destination}) {
  const session = await openSession(handoff, destination);
  try {
    let final;
    try { final = await lstat(session.destination); } catch (error) { if (error.code !== 'ENOENT') throw error; }
    need(!final, 'DELIVERY_FILE_ALREADY_EXISTS');
    const previous = session.state.partial;
    // Only this recorded original writer file is eligible; final output is untouched.
    await session.persist({status:'NEW', partial:null, active:null, reservationTag:null, lastError:null, discarded:previous});
    await removePartial(previous, session.destination);
    await session.persist({discarded:null});
    return {status:'FILE_TRANSFER_RESET', destination:session.destination, statePath:session.statePath,
      removedPartialBytes:previous?.bytes ?? 0};
  } finally { await session.close(); }
}

